INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q23_a1', 'Điều động tàu quay trở 2700 (chữ C) để cứu người', 'gk2_dieudong_q23');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q23_a2', 'Điều động tàu quay trở 1800 (số 8) để cứu người', 'gk2_dieudong_q23');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q23_a3', 'Điều động tàu quay trở ngay lâp tức để cứu người', 'gk2_dieudong_q23');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q23_a4', 'Cả 3 cách trên đều được', 'gk2_dieudong_q23');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_dieudong_q24', 'Câu 24. Tàu đang chạy mà có người ngã xuống nước thì số phao ném cho người ngã là:', 'gk2_dieudong', 24);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q24_a1', '1 phao.', 'gk2_dieudong_q24');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q24_a2', '2 phao.', 'gk2_dieudong_q24');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q24_a3', '3 phao', 'gk2_dieudong_q24');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q24_a4', 'Số phao ném ra không hạn chế miễn sao gần người ngã là được.', 'gk2_dieudong_q24');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_dieudong_q25', 'Câu 25. Khi tàu đang hành trình có người ngã xuống nước, phải cho người nhảy ngay xuống để cứu không:', 'gk2_dieudong', 25);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q25_a1', 'Có', 'gk2_dieudong_q25');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q25_a2', 'Không', 'gk2_dieudong_q25');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q25_a3', 'Tùy từng trường hợp', 'gk2_dieudong_q25');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q25_a4', 'Cho người bơi giỏi nhất nhảy xuống.', 'gk2_dieudong_q25');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_dieudong_q26', 'Câu 26. Điều động tàu thả một neo ngược nước, khi neo chạm đáy nhấp nhẹ cần hãm để neo bám đáy, ban đầu xông một lượng dây neo bằng:', 'gk2_dieudong', 26);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q26_a1', 'Từ 1 đến 1,5 lần độ sâu', 'gk2_dieudong_q26');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q26_a2', 'Từ 1 đến 2 lần độ sâu', 'gk2_dieudong_q26');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q26_a3', 'Từ 1,5 đến 2 lần độ sâu', 'gk2_dieudong_q26');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q26_a4', 'Từ 1,5 đến 2,5 lần độ sâu', 'gk2_dieudong_q26');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_dieudong_q27', 'Câu 27 Điều động tàu thả một neo ngược nước, khi neo bám đáy, cần xông một lượng dây neo bằng:', 'gk2_dieudong', 27);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q27_a1', 'Từ 2 đến 3 lần độ sâu theo quy định.', 'gk2_dieudong_q27');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q27_a2', 'Từ 2 đến 4 lần độ sâu theo quy định.', 'gk2_dieudong_q27');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q27_a3', 'Từ 3 đến 4 lần độ sâu theo quy định.', 'gk2_dieudong_q27');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q27_a4', 'Từ 3 đến 5 lần độ sâu theo quy định.', 'gk2_dieudong_q27');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_dieudong_q28', 'Câu 28. Tàu bị trôi neo do nước chảy siết thì phải?', 'gk2_dieudong', 28);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q28_a1', 'Xông thêm dây neo.', 'gk2_dieudong_q28');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q28_a2', 'Thả thêm neo.', 'gk2_dieudong_q28');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q28_a3', 'Nhổ neo thả lại.', 'gk2_dieudong_q28');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q28_a4', 'Rời vị trí neo', 'gk2_dieudong_q28');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_dieudong_q29', 'Câu 29. Tàu bị trôi neo do chất đáy bám không tốt thì phải?', 'gk2_dieudong', 29);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q29_a1', 'Nhổ neo thả lại.', 'gk2_dieudong_q29');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q29_a2', 'Rời vị trí neo', 'gk2_dieudong_q29');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q29_a3', 'Xông thêm dây neo.', 'gk2_dieudong_q29');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q29_a4', 'Thả thêm neo.', 'gk2_dieudong_q29');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_dieudong_q30', 'Câu 30. Tàu bị trôi neo do nước thủy triều dâng lên thì phải?', 'gk2_dieudong', 30);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q30_a1', 'Rời vị trí neo', 'gk2_dieudong_q30');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q30_a2', 'Nhổ neo thả lại.', 'gk2_dieudong_q30');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q30_a3', 'Xông thêm dây neo.', 'gk2_dieudong_q30');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q30_a4', 'Thả thêm neo.', 'gk2_dieudong_q30');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_dieudong_q31', 'Câu 31. khi tàu đang chạy bị mắc cạn, phải xử lý như thế nào để hạn chế các rủi ro?', 'gk2_dieudong', 31);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q31_a1', 'Lập tức tăng máy để tàu vượt qua chỗ cạn.', 'gk2_dieudong_q31');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q31_a2', 'Lập tức ngừng máy, báo động toàn tàu, báo các tàu chạy gần.', 'gk2_dieudong_q31');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q31_a3', 'Lập tức cho máy lùi để tàu lùi ra khỏi chỗ cạn.', 'gk2_dieudong_q31');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q31_a4', 'Lập tức bẻ lái ra chỗ sâu, tăng máy cho tàu vượt qua.', 'gk2_dieudong_q31');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_dieudong_q32', 'Câu 32. Điều khiển tàu đi đường có ảnh hưởng của gió, nước ngang, để trừ hao độ dạt người điều khiển cần:', 'gk2_dieudong', 32);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q32_a1', 'Tăng tốc độ.', 'gk2_dieudong_q32');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q32_a2', 'Giảm tốc độ.', 'gk2_dieudong_q32');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q32_a3', 'Giữ nguyên tốc đô.', 'gk2_dieudong_q32');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q32_a4', 'Bẻ lái về phía đầu gió, đầu nước.', 'gk2_dieudong_q32');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_dieudong_q33', 'Câu 33. Nguyên nhân nào thường xảy ra nhiều nhất làm cho tàu bị thủng?', 'gk2_dieudong', 33);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q33_a1', 'Do hai tàu đâm nhau, tàu bị đâm vào đá ngầm, xác tàu đắm.', 'gk2_dieudong_q33');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q33_a2', 'Do vỏ tàu yếu, xếp hàng nặng tập trung dẫn tới thủng tàu.', 'gk2_dieudong_q33');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q33_a3', 'Do tàu bị trôi neo, bị mất chủ động làm cho tàu trôi vào bãi đá ngầm.', 'gk2_dieudong_q33');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q33_a4', 'Do tàu bị mắc cạn trên đá mà xử lý không tốt.', 'gk2_dieudong_q33');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_dieudong_q34', 'Câu 34. Biện pháp đề phòng tàu bị thủng?', 'gk2_dieudong', 34);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q34_a1', 'a.Người lái tàu có bằng chuyên môn phù hợp với loại tàu đang điều khiển, có nhiều kinh nghiệm, thuộc đường, lái tàu trong tình trạng thần kinh ổn định.', 'gk2_dieudong_q34');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q34_a2', 'b.Khi xếp hàng nặng xuống tàu phải dùng gỗ lát sàn tàu để phân đều lực ra.', 'gk2_dieudong_q34');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q34_a3', 'c.Trong trường hợp tàu bị mắc cạn trên đá tuyệt đối không được sử dụng máy mà chỉ tìm cách làm giảm mớn nước để tàu nổi nên rồi đưa tàu ra.', 'gk2_dieudong_q34');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q34_a4', 'd.Cả ba đáp án trên', 'gk2_dieudong_q34');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_dieudong_q35', 'Câu 35. Việc đầu tiên phải làm khi tàu bị thủng?', 'gk2_dieudong', 35);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q35_a1', 'Tiến hành xác định vị trí, kích thước lỗ thủng, xác định lượng nước đã tràn vào trong tàu.', 'gk2_dieudong_q35');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q35_a2', 'Tiến hành bị lỗ thủng, bơm nước ra ngoài.', 'gk2_dieudong_q35');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q35_a3', 'Đóng tất cả các van thông nước, cửa kín nước với khoang bị thủng.Gia cường các vách ngăn kín nước với khoang bị thủng.', 'gk2_dieudong_q35');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q35_a4', 'Người đang lái tàu phải lập tức giảm máy hoặc ngừng máy.Báo động toàn tàu, báo cho các tàu chạy gần. Kiểm tra độ nghiêng, chúi từ đó xác định mức độ nguy hiểm của tàu.', 'gk2_dieudong_q35');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_dieudong_q36', 'Câu 36. Phương pháp điều động tàu về bến sau khi bịt lỗ thủy tạm thời:', 'gk2_dieudong', 36);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q36_a1', 'a. Lái tàu chạy với tốc độ nhanh, ở ven bờ, nơi có độ sâu nhỏ.Trong trường hợp có sóng thì phải để lỗ thủng ở mạn dưới sóng để thân tàu che sóng cho lỗ thủng.', 'gk2_dieudong_q36');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q36_a2', 'b.Lái tàu chạy với tốc độ chậm, ở ven bờ, nơi có độ sâu nhỏ.Trong trường hợp có sóng thì phải để lỗ thủng ở mạn dưới sóng để thân tàu che sóng cho lỗ thủng.', 'gk2_dieudong_q36');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q36_a3', 'c.Lái tàu chạy với tốc độ nhanh, ở giữa sông. Trong trường hợp có sóng thì phải để lỗ thủng ở mạn dưới sóng để thân tàu che sóng cho lỗ thủng.', 'gk2_dieudong_q36');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q36_a4', 'd.Lái tàu chạy với tốc độ chậm, ở giữa sông.Trong trường hợp có sóng thì phải để lỗ thủng ở mạn dưới sóng để thân tàu che sóng cho lỗ thủng.', 'gk2_dieudong_q36');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_dieudong_q37', 'Câu 37. Phương pháp tự đưa tàu ra cạn khi tàu bị mắc cạn trên đá?', 'gk2_dieudong', 37);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q37_a1', 'a. Cho máy tới lùi, bẻ lái qua lại nhiều lần để làm cho bùn, cát dưới đáy tàu lỏng ra, sau đó cho lùi mạnh để đưa tàu ra.', 'gk2_dieudong_q37');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q37_a2', 'b. Cho thả neo mạn ngoài (dùng hai xuồng ghép lại để neo ở giữa, đem ra ngoài thả) kết hợp thu neo và máy để đưa tàu ra.', 'gk2_dieudong_q37');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q37_a3', 'Chuyển dây lên bờ, kết hợp thu dây bằng tời và máy để đưa tàu ra.', 'gk2_dieudong_q37');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q37_a4', 'Tìm mọi cách làm giảm mớn nước của tàu để tàu nổi nên (tuyệt đối không được sử dụng máy tránh làm cho tàu bị thủng lớn hơn ...), bằng cách bơm nước, chuyển hàng, dỡ hàng, chờ thủy triều.', 'gk2_dieudong_q37');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_dieudong_q38', 'Câu 38. Phương pháp nào hay được sử dụng nhiều nhất khi tự đưa tàu ra cạn trường hợp tàu bị mắc cạn trên bùn cát?', 'gk2_dieudong', 38);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q38_a1', 'a. Bẻ lái qua lại, cho máy tới lùi nhiều lần để làm cho bùn, cát dưới đáy tàu lỏng ra, sau đó cho lùi mạnh để đưa tàu ra.', 'gk2_dieudong_q38');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q38_a2', 'b. Cho thả neo mạn ngoài (dùng hai xuồng ghép lại để neo ở giữa, đem ra ngoài thả) kết hợp thu neo và máy để đưa tàu ra.', 'gk2_dieudong_q38');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q38_a3', 'Chuyển dây lên bờ, kết hợp thu dây bằng tời và máy để đưa tàu ra.', 'gk2_dieudong_q38');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q38_a4', 'Phải tìm mọi cách làm giảm mớn nước của tàu để tàu nổi nên (tuyệt đối không được sử dụng máy tránh làm cho tàu bị thủng lớn hơn ...), bằng cách bơm nước, chuyển hàng, dỡ hàng, chờ thủy triều.', 'gk2_dieudong_q38');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_dieudong_q39', 'Câu 39. Khi chạy trong đường chập thì?', 'gk2_dieudong', 39);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q39_a1', 'Được phép vượt nhau, tránh nhau.', 'gk2_dieudong_q39');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q39_a2', 'Không được phép vượt nhau.', 'gk2_dieudong_q39');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q39_a3', 'không được phép tránh nhau.', 'gk2_dieudong_q39');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q39_a4', 'Không được phép vượt nhau, tránh nhau.', 'gk2_dieudong_q39');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_dieudong_q40', 'Câu 40. Khi chạy trong đường chập mà có gió ngang thì?', 'gk2_dieudong', 40);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q40_a1', 'a. Phải bẻ lái tàu để mũi tàu thẳng theo đường chập.', 'gk2_dieudong_q40');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q40_a2', 'b. Phải bẻ lái tàu về phía đầu gió.', 'gk2_dieudong_q40');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q40_a3', 'c. Phải bẻ lái tàu về phía cuối gió.', 'gk2_dieudong_q40');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q40_a4', 'd. Thả neo đậu tàu chờ hết gió mới đi.', 'gk2_dieudong_q40');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_dieudong_q41', 'Câu 41. Để hai tàu vượt nhau an toàn thì?', 'gk2_dieudong', 41);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q41_a1', 'Khoảng cách chính ngang giữa hai tàu không nhỏ hơn chiều dài của tàu nhỏ, tốc độ của tàu vượt và tàu bị vượt phải chênh nhau nhiều.', 'gk2_dieudong_q41');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q41_a2', 'Khoảng cách chính ngang giữa hai tàu không nhỏ hơn chiều dài của tàu lớn, tốc độ của tàu vượt và tàu bị vượt không cần chênh nhau nhiều.', 'gk2_dieudong_q41');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q41_a3', 'Khoảng cách chính ngang giữa hai tàu không nhỏ hơn chiều dài của tàu nhỏ, tốc độ của tàu vượt và tàu bị vượt không cần chênh nhau nhiều', 'gk2_dieudong_q41');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q41_a4', 'Khoảng cách chính ngang giữa hai tàu không nhỏ hơn chiều dài của tàu lớn, tốc độ của tàu vượt và tàu bị vượt phải chênh nhau nhiều.', 'gk2_dieudong_q41');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_dieudong_q42', 'Câu 42. Để hai tàu tránh nhau an toàn thì?', 'gk2_dieudong', 42);
