INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q43_a4', 'd. Khoảng cách chính ngang giữa tàu và bờ không nhỏ hơn chiều dài tàu, không cần thay đổi tốc độ.', 'gk2_dieudong_q43');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_dieudong_q44', 'Câu 44. Điều động tàu khi có xương mù thì?', 'gk2_dieudong', 44);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q44_a1', 'a.Phải giảm tốc độ, phát âm hiệu, bật đèn hành trình, neo phải được chuẩn bị sẵn sàng để thả.', 'gk2_dieudong_q44');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q44_a2', 'b. Phải giảm tốc độ, tăng cường cảnh giới, bật đèn hành trình, neo phải được chuẩn bị sẵn sàng để thả.', 'gk2_dieudong_q44');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q44_a3', 'c.Phải giảm tốc độ, tăng cường cảnh giới, phát âm hiệu, neo phải được chuẩn bị sẵn sàng để thả.', 'gk2_dieudong_q44');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q44_a4', 'd.Phải giảm tốc độ, tăng cường cảnh giới, phát âm hiệu, bật đèn hành trình, neo phải được chuẩn bị sẵn sàng để thả.', 'gk2_dieudong_q44');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_dieudong_q45', 'Câu 45. Điều động tàu khi có xương mù dày đặc không thể chạy được thì?', 'gk2_dieudong', 45);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q45_a1', 'a.Cho thả neo, bật đèn neo, tăng cường cảnh giới để đề phòng các phương tiện khác đâm vào mình.', 'gk2_dieudong_q45');
