INSERT INTO answers (id, text, question_id) VALUES ('gk2_dieudong_q45_a3', 'c.Cho thả neo, bật đèn neo, phát âm hiệu (cách hai phút phát hai tiếng còi dài) để báo tàu đã dừng lại.', 'gk2_dieudong_q45');
