INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_kttv_q1', 'Câu 01: Thế nào là nhật triều?', 'gk2_kttv', 1);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q1_a1', 'Là hiện tượng xảy ra trong một ngày đêm trăng (24h50’) có 1 lần triều lên và 1 lần triều xuống.', 'gk2_kttv_q1');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q1_a2', 'Là hiện tượng xảy ra trong một ngày đêm trăng (24h50’) có 2 lần triều lên và 2 lần triều xuống.', 'gk2_kttv_q1');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q1_a3', 'Là hiện tượng xảy ra trong một ngày đêm trăng (24h50’) có 1 lần triều lên và 2 lần triều xuống.', 'gk2_kttv_q1');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q1_a4', 'Là hiện tượng xảy ra trong một ngày đêm trăng (24h50’) có 2 lần triều lên và 1 lần triều xuống.', 'gk2_kttv_q1');
