INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q2_a1', 'Là hiện tượng xảy ra trong một ngày đêm trăng (24h50’) có 1 lần triều lên và 1 lần triều xuống.', 'gk2_kttv_q2');
