INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q5_a4', 'Nhật triều không đều', 'gk2_kttv_q5');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_kttv_q6', 'Câu 06: Thế nào là độ cao thủy triều (H)?', 'gk2_kttv', 6);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q6_a1', 'Là độ cao mực nước tính từ đáy biển đến ki tàu tại thời điểm quan trắ', 'gk2_kttv_q6');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q6_a2', 'Là độ cao mực nước tính từ đáy biển đến mớn nước hiện tại của tàu tại thời điểm quan trắ', 'gk2_kttv_q6');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q6_a3', 'Là độ cao mực nước tính từ đáy biển đến mớn nước trung bình của tàu tại thời điểm quan trắ', 'gk2_kttv_q6');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q6_a4', 'Là độ cao mực nước trên số “0” độ sâu tại thời điểm quan trắC', 'gk2_kttv_q6');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_kttv_q7', 'Câu 07: Thế nào là biên độ triều (B)?', 'gk2_kttv', 7);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q7_a1', 'Là khoảng cách thẳng đứng giữa mực nước lớn và đáy biển.', 'gk2_kttv_q7');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q7_a2', 'Là khoảng cách thẳng đứng giữa mực nước ròng và đáy biển.', 'gk2_kttv_q7');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q7_a3', 'Là khoảng cách thẳng đứng giữa mực nước lớn và số 0 độ sâu.', 'gk2_kttv_q7');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q7_a4', 'Là khoảng cách thẳng đứng giữa mực nước lớn và nước ròng kế tiếp.', 'gk2_kttv_q7');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_kttv_q8', 'Câu 8: Biên độ thủy triều đạt cao nhất ở chế độ :', 'gk2_kttv', 8);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q8_a1', 'Bán nhật triều.', 'gk2_kttv_q8');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q8_a2', 'Nhật triều.', 'gk2_kttv_q8');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q8_a3', 'Tạp triều.', 'gk2_kttv_q8');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q8_a4', 'Triều hỗn hợp', 'gk2_kttv_q8');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_kttv_q9', 'Câu 9: Thuỷ triều là?', 'gk2_kttv', 9);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q9_a1', 'Hiện tượng dao động của mực nước biển và đại dương có chu kỳ, dưới tác động của lực hấp dẫn vũ trụ từ mặt trời.', 'gk2_kttv_q9');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q9_a2', 'Hiện tượng dao động của mực nước biển và đại dương có chu kỳ, dưới tác động của lực hấp dẫn vũ trụ từ mặt trăng.', 'gk2_kttv_q9');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q9_a3', 'Hiện tượng dao động của mực nước biển và đại dương có chu kỳ, dưới tác động của lực hấp dẫn vũ trụ từ mặt trăng và mặt trời.', 'gk2_kttv_q9');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q9_a4', 'Hiện tượng dao động của mực nước biển và đại dương có chu kỳ, dưới tác động của lực hấp dẫn vũ trụ từ các hành tinh trong hệ mặt trời.', 'gk2_kttv_q9');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_kttv_q10', 'Câu 10: Nước ta có các chế độ thủy triều nào?', 'gk2_kttv', 10);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q10_a1', 'Nhật triều, bán nhật triều, triều hỗn hợp', 'gk2_kttv_q10');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q10_a2', 'Nhật triều, bán nhật triều', 'gk2_kttv_q10');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q10_a3', 'Bán nhật triều, triều hỗn hợp, triều sóc vọng', 'gk2_kttv_q10');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q10_a4', 'Nhật triều, triều sóc vọng, triều trực thế.', 'gk2_kttv_q10');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_kttv_q11', 'Câu 11) Khi có dòng chảy phủ luồng, ta xác định luồng chạy tàu an toàn như thế nào?', 'gk2_kttv', 11);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q11_a1', 'Mặt sông xuất hiện nước cuộn, nhiều ngấn nước, sóng nhấp nhô hoặc sóng ngang, bước sóng ngắn, gợn lăn tăn và có cả những xoáy nước hay bọt nước.', 'gk2_kttv_q11');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q11_a2', 'Mặt sông có dòng chảy mà vệt nước dài liên tục, bề mặt dòng chảy êm, lưu tốc dòng chảy mạnh.', 'gk2_kttv_q11');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q11_a3', 'Mặt sông có dòng chảy lưu tốc chậm, mặt nước sáng, có sóng gợn lăn tăn, tỏa màu lấp lánh hoặc mặt nước xáo động, thỉnh thoảng có sóng cuộn hay có bọt nước, mặt nước không êm thiếu ổn định và không liên tục', 'gk2_kttv_q11');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q11_a4', 'Cả 3 đáp án đều đúng.', 'gk2_kttv_q11');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_kttv_q12', 'Câu 12) Dòng chảy vật thường xuất hiện ở khu vực nào ?', 'gk2_kttv', 12);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q12_a1', 'Xuất hiện ở những nơi có mực nước cao, đột ngột đổ xuống thấp rồi lan tỏa ra nhiều hướng hoặc những nơi giữa luồng sông có đá ngầm, bãi ngầm, bãi cát, hòn nổi.', 'gk2_kttv_q12');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q12_a2', 'Xuất hiện ở những nơi sông cong, dòng nước đến chổ bị uốn cong thì tập trung đổ thẳng về phía bờ lõm (bờ vịnh), bị bờ ngăn lại, dòng chảy lại quay hướng xuống đáy và đổ ngang về phía bờ lồi.', 'gk2_kttv_q12');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q12_a3', 'Xuất hiện ở khúc sông thẳng, vào mùa nước lớn, nhất là những ngày có lũ, mực nước sông dâng lên cao đột ngột.', 'gk2_kttv_q12');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q12_a4', 'Xuất hiện ở đoạn sông có bờ lõm vào, do dòng chảy đang đi thẳng gặp phải bờ lõm sẽ bị thay đổi hướng một cách đột ngột tạo nên hiện tượng chảy rối và dần dần đi theo hướng trôn ốc từ trên xuống dưới', 'gk2_kttv_q12');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_kttv_q13', 'Câu 13) Nguyên nhân nào hình thành xoáy âm áp?', 'gk2_kttv', 13);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q13_a1', 'Do dòng nước đang đi thẳng gặp bờ lồi hay ghềnh đá, chướng ngại vật ăn nhô ra sông, làm cho dòng chảy thay đổi chiều đột ngột, chảy cuộn tròn theo hình trôn ốc từ dưới lên trên', 'gk2_kttv_q13');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q13_a2', 'Do dòng chảy đang đi thẳng gặp phải bờ lõm sẽ bị thay đổi hướng một cách đột ngột tạo nên hiện tượng chảy rối và dần dần đi theo hướng trôn ốc từ trên xuống dưới, làm cho nước hình thành một vùng có chiều dòng chảy cuộn tròn đi xuống.', 'gk2_kttv_q13');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q13_a3', 'Do dòng nước chảy đến chổ bị uốn cong thì tập trung đổ thẳng về phía bờ lõm (bờ vịnh), bị bờ ngăn lại, dòng chảy lại quay hướng xuống đáy và đổ ngang về phía bờ lồi (bờ doi)', 'gk2_kttv_q13');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q13_a4', 'Tất cả các đáp án trên đều đúng.', 'gk2_kttv_q13');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_kttv_q14', 'Câu 14) Nguyên nhân nào hình thành dòng chảy xoáy trục ngang?', 'gk2_kttv', 14);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q14_a1', 'do dòng nước đang đi thẳng gặp bờ lồi hay ghềnh đá, chướng ngại vật ăn nhô ra sông, làm cho dòng chảy thay đổi chiều đột ngột, chảy cuộn tròn theo hình trôn ốc từ dưới lên trên', 'gk2_kttv_q14');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q14_a2', 'Do dòng chảy đang đi thẳng gặp phải bờ lõm sẽ bị thay đổi hướng một cách đột ngột tạo nên hiện tượng chảy rối và dần dần đi theo hướng trôn ốc từ trên xuống dưới, làm cho nước hình thành một vùng có chiều dòng chảy cuộn tròn đi xuống.', 'gk2_kttv_q14');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q14_a3', 'Do dòng chảy đang đi thẳng do gặp đáy sông không bằng phẳng dạng bậc thềm (tam cấp) nên bị mất thăng bằng và đâm thẳng xuống đáy, sau đó mới ngóc lên lại bị dòng nước trên mặt xô tới buộc chúng phải chảy cuộn tròn quanh đường trục nằm ngang.', 'gk2_kttv_q14');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q14_a4', 'Do dòng nước chảy đến chổ bị uốn cong thì tập trung đổ thẳng về phía bờ lõm (bờ vịnh), bị bờ ngăn lại, dòng chảy lại quay hướng xuống đáy và đổ ngang về phía bờ lồi (bờ doi)', 'gk2_kttv_q14');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_kttv_q15', 'Câu 15: Khu vực nào thường sinh ra cồn bãi nhiều nhất?', 'gk2_kttv', 15);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q15_a1', 'Thượng lưu.', 'gk2_kttv_q15');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q15_a2', 'Trung lưu.', 'gk2_kttv_q15');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q15_a3', 'Hạ lưu.', 'gk2_kttv_q15');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q15_a4', 'Trung lưu - Hạ lưu.', 'gk2_kttv_q15');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_kttv_q16', 'Câu 16: Khu vực thượng lưu thường có đặc điểm gì?', 'gk2_kttv', 16);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q16_a1', 'Độ dốc lớn, lưu tốc lớn và có nhiều bãi cạn.', 'gk2_kttv_q16');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q16_a2', 'Độ dốc lớn, lưu tốc nhỏ và có nhiều ghềnh đá nguy hiểm.', 'gk2_kttv_q16');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q16_a3', 'Độ dốc lớn, lưu tốc lớn , nhiều ghềnh đá nguy hiểm.', 'gk2_kttv_q16');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q16_a4', 'Độ dốc lớn, lưu tốc nhỏ', 'gk2_kttv_q16');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_kttv_q17', 'Câu 17: Dạng đoạn sông cong thường có đặc điểm gì?', 'gk2_kttv', 17);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q17_a1', 'Bên bờ vịnh thường có bãi cạn.', 'gk2_kttv_q17');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q17_a2', 'Bên bờ doi thường có bãi cạn.', 'gk2_kttv_q17');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q17_a3', 'Cả hai bên ven bờ thường có bãi cạn.', 'gk2_kttv_q17');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q17_a4', 'Ở giữa sông có bãi cạn', 'gk2_kttv_q17');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_kttv_q18', 'Câu 18: Dòng chảy vặn thường xuất hiện khi dòng chảy gặp phải địa hình gì?', 'gk2_kttv', 18);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q18_a1', 'Đoạn sông cong.', 'gk2_kttv_q18');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q18_a2', 'Đoạn sông có dòng chảy phân luồng.', 'gk2_kttv_q18');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q18_a3', 'Đoạn sông có dòng chảy phủ luồng', 'gk2_kttv_q18');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q18_a4', 'Đoạn sông thẳng', 'gk2_kttv_q18');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_kttv_q19', 'Câu 19: Dòng chảy phân luồng thường xuất hiện khi nào?', 'gk2_kttv', 19);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q19_a1', 'a. Có cồn ở giữa sông', 'gk2_kttv_q19');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q19_a2', 'b. Có cồn ở bờ phải', 'gk2_kttv_q19');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q19_a3', 'c. Có cồn ở bờ trái', 'gk2_kttv_q19');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q19_a4', 'd. Có cồn ở cả hai bên bờ', 'gk2_kttv_q19');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_kttv_q20', 'Câu 20: Dòng nước chảy xoáy thường xuất hiện ở đâu?', 'gk2_kttv', 20);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q20_a1', 'a. Nơi bờ sông bị lở đột ngột, nơi có các công trình ngầm hoặc chướng ngại vật', 'gk2_kttv_q20');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q20_a2', 'b. Nơi sông thẳng', 'gk2_kttv_q20');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q20_a3', 'c. Nơi sông cong đều', 'gk2_kttv_q20');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q20_a4', 'd. Nơi cửa sông', 'gk2_kttv_q20');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_ktvt_q1', 'CÂU HỎI MÔN KINH TẾ VẬN TẢI: 20 câu', 'gk2_ktvt', 1);
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_ktvt_q2', 'Câu 1: Người kinh doanh vận tải hàng hóa không có nghĩa vụ:', 'gk2_ktvt', 2);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q2_a1', 'a. Cung cấp phương tiện đúng chủng loại, đúng địa điểm, bảo quản hàng hóa trong quá trình vận tải và giao hàng hóa cho người nhận hàng theo thỏa thuận trong hợp đồng.', 'gk2_ktvt_q2');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q2_a2', 'b. Hướng dẫn xếp, dỡ hàng hóa trên phương tiện', 'gk2_ktvt_q2');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q2_a3', 'c. Chuẩn bị đầy đủ giấy tờ hợp pháp về hàng hóa, đóng gói hàng hóa đúng quy cách, ghi ký hiệu, mã hiệu hàng hóa đầy đủ rõ ràng', 'gk2_ktvt_q2');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q2_a4', 'd. Thông báo cho người thuê vận tải biết thời gian phương tiện đến cảng, bến và thời gian phương tiện đã làm xong thủ tục vào cảng, bến.', 'gk2_ktvt_q2');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_ktvt_q3', 'Câu 2: Người thuê vận tải hàng hóa không có nghĩa vụ:', 'gk2_ktvt', 3);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q3_a1', 'a. Cung cấp giấy tờ, tài liệu và các thông tin cần thiết khác về hàng hóa và đảm bảo tính pháp lý của hàng hóa.', 'gk2_ktvt_q3');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q3_a2', 'b. Thanh toán cước phí vận tải và chi phí phát sinh cho người kinh doanh vận tải hàng hoá;', 'gk2_ktvt_q3');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q3_a3', 'c. Cử người áp tải hàng hoá trong quá trình vận tải đối với loại hàng hoá bắt buộc phải có người áp tải.', 'gk2_ktvt_q3');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q3_a4', 'd. Lập giấy vận chuyển theo mẫu quy định.', 'gk2_ktvt_q3');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_ktvt_q4', 'Câu 3: Người thuê vận tải hàng hóa có quyền:', 'gk2_ktvt', 4);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q4_a1', 'a. Từ chối xếp hàng hoá lên phương tiện mà người kinh doanh vận tải đã bố trí nếu phương tiện không phù hợp để vận tải loại hàng hoá đã thoả thuận trong hợp đồng.', 'gk2_ktvt_q4');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q4_a2', 'b. Yêu cầu người kinh doanh vận tải xác nhận số lượng, niêm phong đối với hàng hóa mà mình gửi đi;', 'gk2_ktvt_q4');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q4_a3', 'c. Yêu cầu người kinh doanh vận tải giao hàng hoá đúng địa điểm, thời gian đã thoả thuận trong hợp đồng.', 'gk2_ktvt_q4');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q4_a4', 'd. Cả ba ý trên.', 'gk2_ktvt_q4');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_ktvt_q5', 'Câu 4: Người kinh doanh vận tải hàng hóa có quyền:', 'gk2_ktvt', 5);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q5_a1', 'a. Yêu cầu người thuê vận tải hàng hóa mở bao, kiện để kiểm tra trong trường hợp nghi ngờ về tính xác thực của việc khai báo chủng loại hàng hóa.', 'gk2_ktvt_q5');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q5_a2', 'b. Từ chối vận tải nếu người thuê vận tải không giao hàng hóa theo thỏa thuận trong hợp đồng;', 'gk2_ktvt_q5');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q5_a3', 'c. Yêu cầu trả tiền lưu hàng hóa trên phương tiện do lỗi của người thuê vận tải, người nhận hàng gây ra.', 'gk2_ktvt_q5');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q5_a4', 'd. Cả ba ý trên.', 'gk2_ktvt_q5');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_ktvt_q6', 'Câu 5. Hàng hóa siêu trường, siêu trọng có kích thước, trọng lượng thực tế là:', 'gk2_ktvt', 6);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q6_a1', 'Chiều rộng trên 10 mét hoặc chiều dài trên 30 mét hoặc chiều cao trên 4,5 mét, trọng lượng trên 50 tấn.', 'gk2_ktvt_q6');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q6_a2', 'Chiều rộng trên 10 mét hoặc chiều dài trên 40 mét hoặc chiều cao trên 3,5 mét, trọng lượng trên 50 tấn.', 'gk2_ktvt_q6');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q6_a3', 'Chiều rộng trên 10 mét hoặc chiều dài trên 30 mét hoặc chiều cao trên 3,5 mét, trọng lượng trên 100 tấn.', 'gk2_ktvt_q6');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q6_a4', 'Chiều rộng trên 10 mét hoặc chiều dài trên 40 mét hoặc chiều cao trên 4,5 mét, trọng lượng trên 100 tấn.', 'gk2_ktvt_q6');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_ktvt_q7', 'Câu 6.Khi giao hàng hóa theo nguyên hầm kẹp chì nếu niêm phong, kẹp chì còn nguyên vẹn thì người kinh doanh vận tải:', 'gk2_ktvt', 7);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q7_a1', 'Phải chịu trách nhiệm về hàng hóa.', 'gk2_ktvt_q7');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q7_a2', 'Tùy từng trường hợp mà phải chịu trách nhiệm về hàng hóa.', 'gk2_ktvt_q7');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q7_a3', 'Phải chịu trách nhiệm 50% về hàng hóa.', 'gk2_ktvt_q7');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q7_a4', 'Không phải chịu trách nhiệm về hàng hóa.', 'gk2_ktvt_q7');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_ktvt_q8', 'Câu 7. Cách xác định trọng lượng hàng bằng vạch mớn nước trên vỏ tàu có đặc điểm:', 'gk2_ktvt', 8);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q8_a1', 'Nhanh chóng.', 'gk2_ktvt_q8');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q8_a2', 'Chính xác.', 'gk2_ktvt_q8');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q8_a3', 'Chỉ dùng xác định các loại hàng có khối lượng nhỏ.', 'gk2_ktvt_q8');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q8_a4', 'Dùng để xác định hàng hóa có giá trị cao.', 'gk2_ktvt_q8');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_ktvt_q9', 'Câu 8. Trên đường vận tải nếu phát hiện hàng hóa thông thường không đúng với kê khai của người thuê vận tải thì người kinh doanh vận tải xử lý:', 'gk2_ktvt', 9);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q9_a1', 'Báo cho người thuê vận tải biết và tiếp tục vận tải đến nơi trả hàng.', 'gk2_ktvt_q9');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q9_a2', 'Báo cho người thuê vận tải biết và cho tàu dừng lại.', 'gk2_ktvt_q9');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q9_a3', 'Báo cho người thuê vận tải biết và vận tải quay về nơi nhận hàng.', 'gk2_ktvt_q9');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q9_a4', 'Không báo cho người thuê vận tải biết và tiếp tục vận tải đến nơi trả hàng.', 'gk2_ktvt_q9');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_ktvt_q10', 'Câu 9. Phương tiện vận tải bị trưng dụng do lệnh của cơ quan có thẩm quyền thì thuyền trưởng phải:', 'gk2_ktvt', 10);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q10_a1', 'Thông báo cho người kinh doanh vận tải biết.', 'gk2_ktvt_q10');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_ktvt_q10_a2', 'Thông báo cho người thuê vận tải biết.', 'gk2_ktvt_q10');
